function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function drawTile(x,y,sx,sy){const v=tile[idx(x,y)],n=noise(x,y);let base;if(x>=46&&x<=53&&!(y>=19&&y<=20)){base=n>.48?'#626557':'#55594e';rect(sx,sy,16,16,base);rect(sx+2,sy+3,7,3,'#76796a');rect(sx+10,sy+10,4,3,'#494f48');if(n>.66)rect(sx+12,sy+4,2,2,'#888879');return;}
 const east=x>54;const biome=east?'#3b4030':'#354a32';base=n>.72?(east?'#47412e':'#42523a'):biome;rect(sx,sy,16,16,base);
 // subtle grass pixel flecks
 if(n>.22){rect(sx+((x*7+y*3)%13)+1,sy+((y*5+x)%13)+1,2,1,east?'#53503a':'#50613c');}
 if((x<46||x>53)&&n>.91){ // oak / ash trees
 rect(sx+3,sy+11,10,5,'#262c22');rect(sx+5,sy+2,7,11,east?'#4b4030':'#536b42');rect(sx+3,sy+5,10,7,east?'#564a34':'#60794a');rect(sx+6,sy+12,4,4,'#604633');rect(sx+5,sy+5,2,2,east?'#706044':'#788e52');return;}
 const pathY=x<18?19:x<34?24:x<45?17:x<54?19:x<70?22:x<84?12:25;
 if(Math.abs(y-pathY)<=1&&x>4&&x<96){rect(sx,sy,16,16,(x>=46&&x<=53)?'#827653':'#786d4c');if(noise(x+11,y+3)>.56)rect(sx+4,sy+6,3,2,'#9b8959');if(noise(x+9,y+8)>.61)rect(sx+11,sy+12,2,2,'#594e39');}
}
function drawLandmark(cx,cy,kind,label){let x=cx*T-cam.x,y=cy*T-cam.y;if(x<-70||x>canvas.width+70||y<-50||y>canvas.height+30)return;
 if(kind==='camp'){rect(x-25,y-14,50,27,'#262b22');rect(x-21,y-11,42,21,'#796c4d');rect(x-17,y-8,34,15,'#403d2d');rect(x-8,y-6,16,11,'#aa7546');rect(x-3,y-17,6,12,'#d58b4d');rect(x-1,y-22,2,8,'#f1bd62');}
 if(kind==='keep'){rect(x-26,y-19,52,39,'#272c28');rect(x-22,y-15,44,31,'#706c59');rect(x-17,y-10,34,25,'#4e5044');rect(x-21,y-20,9,13,'#8e8770');rect(x+12,y-20,9,13,'#8e8770');rect(x-6,y+3,12,12,'#22231e');rect(x-3,y-6,6,5,'#d6a957');}
 if(kind==='chest'){rect(x-7,y+2,15,10,'#75462e');rect(x-7,y+1,15,4,'#bb8950');rect(x-1,y+3,3,3,'#eed078');}
 if(kind==='bridge'){for(let i=-5;i<=5;i++){rect(x+i*5,y-7,4,20,'#957d54');rect(x+i*5,y-7,4,2,'#c4a56a');}rect(x-28,y-9,56,3,'#554c38');rect(x-28,y+11,56,3,'#554c38');}
 ctx.font='7px monospace';ctx.textAlign='center';ctx.fillStyle='#eee0b2';ctx.fillText(label,x,y+29);ctx.textAlign='left';}
function drawActor(x,y,kind,face,frame,hit){let sx=Math.round(x*T-cam.x),sy=Math.round(y*T-cam.y);if(hit>0){rect(sx-5,sy-10,11,15,'#fff4c4');return}
 if(kind==='hero'){// shadow, boots, cloak, face, sword
 rect(sx-6,sy+4,12,4,'#20251d');rect(sx-4,sy+3,3,4,'#544032');rect(sx+1,sy+3,3,4,'#544032');rect(sx-5,sy-5,10,10,'#416548');rect(sx-6,sy-2,12,6,'#35543b');rect(sx-4,sy-10,8,7,'#c99867');rect(sx-5,sy-12,10,4,'#a8a17c');rect(sx-3,sy-9,2,2,'#28251f');rect(sx+2,sy-9,2,2,'#28251f');if(face==='left')rect(sx-8,sy-1,2,8,'#d4c08c');else if(face==='right')rect(sx+6,sy-1,2,8,'#d4c08c');else rect(sx+4,sy-1,2,8,'#d4c08c');if(frame%2===0)rect(sx-4,sy+5,3,2,'#d2b178');}
 else {rect(sx-7,sy+3,14,4,'#22241e');rect(sx-5,sy-6,10,10,kind==='boss'?'#632f39':'#84533d');rect(sx-4,sy-11,8,7,kind==='boss'?'#c5ad84':'#cab38b');rect(sx-5,sy-13,10,4,kind==='boss'?'#7a3440':'#63805b');rect(sx-7,sy-12,4,4,'#d6c69a');rect(sx+3,sy-12,4,4,'#d6c69a');rect(sx-2,sy-9,2,2,'#6c2d35');rect(sx+2,sy-9,2,2,'#6c2d35');if(kind==='boss'){rect(sx-8,sy-16,16,3,'#ddbc68');rect(sx-5,sy-20,2,5,'#ddbc68');rect(sx+3,sy-20,2,5,'#ddbc68');}}
}
function draw(){const px=player.x*T,py=player.y*T;cam.x=Math.max(0,Math.min(W*T-canvas.width,px-canvas.width/2));cam.y=Math.max(0,Math.min(H*T-canvas.height,py-canvas.height/2));ctx.clearRect(0,0,480,288);let x0=Math.max(0,Math.floor(cam.x/T)),y0=Math.max(0,Math.floor(cam.y/T));for(let y=y0;y<Math.min(H,y0+20);y++)for(let x=x0;x<Math.min(W,x0+33);x++)drawTile(x,y,x*T-cam.x,y*T-cam.y);
 // locations
 drawLandmark(12,19,'camp','ALTES LAGER');drawLandmark(9,22,'chest','');drawLandmark(28,24,'camp','MONDQUELL');drawLandmark(41,17,'keep','DORNENFESTE');drawLandmark(50,20,'bridge','GEBIRGSPASS');drawLandmark(61,22,'camp','PASSWACHT');drawLandmark(77,12,'camp','ASCHENWALD');drawLandmark(92,25,'keep','SMARAGDTHRON');
 // active marker
 if(stage<stages.length){const [lx,ly]=stages[stage].center;let bx=lx*T-cam.x,by=ly*T-cam.y;ctx.fillStyle='#f0cb70';ctx.beginPath();ctx.moveTo(bx,by-32-Math.sin(performance.now()/220)*2);ctx.lineTo(bx-5,by-24-Math.sin(performance.now()/220)*2);ctx.lineTo(bx+5,by-24-Math.sin(performance.now()/220)*2);ctx.fill();}
 for(const e of enemies){drawActor(e.x,e.y,e.boss?'boss':'enemy','down',Math.floor(performance.now()/180),e.hit);let sx=e.x*T-cam.x,sy=e.y*T-cam.y;rect(sx-7,sy-18,14,2,'#342824');rect(sx-7,sy-18,14*Math.max(0,e.hp/e.max),2,e.boss?'#e1ba54':'#d66049');}
 if(player.atk>0){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[player.face],sx=player.x*T-cam.x+d[0]*15,sy=player.y*T-cam.y+d[1]*15;rect(sx-2,sy-4,4,8,'#f4d57d');rect(sx-5,sy-1,10,2,'#fff0bb');}
 drawActor(player.x,player.y,'hero',player.face,Math.floor(performance.now()/180),0);
 if(stage<3){let gx=50*T-cam.x,gy=20*T-cam.y;if(gx>0&&gx<480&&gy>0&&gy<288){ctx.fillStyle='#e7d394';ctx.font='8px monospace';ctx.textAlign='center';ctx.fillText('WESTEN ZUERST BEFREIEN',gx,gy+40);ctx.textAlign='left';}}
}
function update(dt){if(!gameStarted)return;player.atk=Math.max(0,player.atk-dt);player.invul=Math.max(0,player.invul-dt);for(const e of enemies){e.hit=Math.max(0,e.hit-dt);e.walk+=dt;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(d<7&&d>1.05){let s=(e.boss?1.05:.75)*dt,nx=e.x+dx/d*s,ny=e.y+dy/d*s;if(canStand(nx,e.y))e.x=nx;if(canStand(e.x,ny))e.y=ny;}if(d<1.1&&player.invul<=0){player.hp-=e.boss?13:8;player.invul=.8;shake=5;updateUI();if(player.hp<=0){player.hp=player.max;player.x=Math.max(5,stages[Math.min(stage,5)].center[0]-4);player.y=stages[Math.min(stage,5)].center[1]+3;enemies.forEach(m=>{m.x=stages[Math.min(stage,5)].center[0]+(Math.random()-.5)*5;m.y=stages[Math.min(stage,5)].center[1]+(Math.random()-.5)*5});toast('Du wurdest zurückgedrängt · Leben aufgefüllt');save();}}}
 let dx=0,dy=0;if(keys.has('ArrowUp')||keys.has('w'))dy--;if(keys.has('ArrowDown')||keys.has('s'))dy++;if(keys.has('ArrowLeft')||keys.has('a'))dx--;if(keys.has('ArrowRight')||keys.has('d'))dx++;if(dx&&dy){dx*=.707;dy*=.707}tryMove(dx,dy,dt);updateUI();}
let last=performance.now();function loop(now){let dt=Math.min(.04,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);

