95:  for(const e of enemies){drawActor(e.x,e.y,e.boss?'boss':'enemy','down',Math.floor(performance.now()/180),e.hit);let sx=e.x*T-cam.x,sy=e.y*T-cam.y;rect(sx-7,sy-18,14,2,'#342824');rect(sx-7,sy-18,14*Math.max(0,e.hp/e.max),2,e.boss?'#e1ba54':'#d66049');}
96:  if(player.atk>0){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[player.face],sx=player.x*T-cam.x+d[0]*15,sy=player.y*T-cam.y+d[1]*15;rect(sx-2,sy-4,4,8,'#f4d57d');rect(sx-5,sy-1,10,2,'#fff0bb');}
97:  drawActor(player.x,player.y,'hero',player.face,Math.floor(performance.now()/180),0);
98:  if(stage<3){let gx=50*T-cam.x,gy=20*T-cam.y;if(gx>0&&gx<480&&gy>0&&gy<288){ctx.fillStyle='#e7d394';ctx.font='8px monospace';ctx.textAlign='center';ctx.fillText('WESTEN ZUERST BEFREIEN',gx,gy+40);ctx.textAlign='left';}}
99: }
100: function update(dt){if(!gameStarted)return;player.atk=Math.max(0,player.atk-dt);player.invul=Math.max(0,player.invul-dt);for(const e of enemies){e.hit=Math.max(0,e.hit-dt);e.walk+=dt;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(d<7&&d>1.05){let s=(e.boss?1.05:.75)*dt,nx=e.x+dx/d*s,ny=e.y+dy/d*s;if(canStand(nx,e.y))e.x=nx;if(canStand(e.x,ny))e.y=ny;}if(d<1.1&&player.invul<=0){player.hp-=e.boss?13:8;player.invul=.8;shake=5;updateUI();if(player.hp<=0){player.hp=player.max;player.x=Math.max(5,stages[Math.min(stage,5)].center[0]-4);player.y=stages[Math.min(stage,5)].center[1]+3;enemies.forEach(m=>{m.x=stages[Math.min(stage,5)].center[0]+(Math.random()-.5)*5;m.y=stages[Math.min(stage,5)].center[1]+(Math.random()-.5)*5});toast('Du wurdest zurückgedrängt · Leben aufgefüllt');save();}}}
