(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=44,H=30,T=16,keys=new Set(),tiles=new Uint8Array(W*H),arrows=[];
const el=id=>document.getElementById(id);let toastTimer;
const player={x:8.5,y:14.5,hp:100,max:100,st:100,maxSt:100,level:1,xp:0,kills:0,face:'right',atk:0,invul:0,dodge:0,blocking:false,stDelay:0,potions:0,combo:0};
let phase=0,enemies=[],gameStarted=false,gameWon=false,shake=0,cam={x:0,y:0},captainTalk=false,chestOpen=false;
const saveKey='eisenwacht-ch1-save';let saved=null;try{saved=JSON.parse(localStorage.getItem(saveKey)||'null')}catch{}
const noise=(x,y)=>{let n=x*374761393+y*668265263;n=(n^(n>>13))*1274126177;return((n^(n>>16))>>>0)/4294967295};
function idx(x,y){return y*W+x}function inside(x,y){return x>=0&&y>=0&&x<W&&y<H}
function makeMap(){for(let y=0;y<H;y++)for(let x=0;x<W;x++)tiles[idx(x,y)]=0;
 // outer edges and bramble fence
 for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(x===0||y===0||x===W-1||y===H-1)tiles[idx(x,y)]=1;
 // Eisenwacht: broad stone courtyard, crenellated wall, only eastern gate open
 for(let y=5;y<=22;y++)for(let x=3;x<=17;x++)tiles[idx(x,y)]=3;
 for(let x=3;x<=17;x++){tiles[idx(x,5)]=2;tiles[idx(x,22)]=2}
 for(let y=5;y<=22;y++){tiles[idx(3,y)]=2;if(y<12||y>15)tiles[idx(17,y)]=2}
 // buildings, yard paving, gate approach
 for(let y=7;y<=11;y++)for(let x=5;x<=8;x++)tiles[idx(x,y)]=2;
 for(let y=7;y<=10;y++)for(let x=12;x<=15;x++)tiles[idx(x,y)]=2;
 for(let y=12;y<=15;y++)for(let x=17;x<=22;x++)tiles[idx(x,y)]=0;
 // path, scrub and tree line outside the fortress
 for(let x=17;x<40;x++)for(let y=11;y<=16;y++)if(noise(x,y)>.77)tiles[idx(x,y)]=0;
 for(let y=2;y<H-2;y++)for(let x=20;x<W-2;x++)if(noise(x,y)>.92&&!(x>=21&&x<=37&&y>=10&&y<=18))tiles[idx(x,y)]=1;
 // clear skirmish field and paths
 for(let y=8;y<=21;y++)for(let x=22;x<=38;x++)if((x-30)**2/170+(y-15)**2/60<1)tiles[idx(x,y)]=0;
 for(let x=17;x<=39;x++)for(let y=13;y<=15;y++)tiles[idx(x,y)]=0;
}
function save(){try{localStorage.setItem(saveKey,JSON.stringify({phase,hp:player.hp,st:player.st,xp:player.xp,kills:player.kills,level:player.level,potions:player.potions,chestOpen,captainTalk,gameWon}))}catch{}}
function makeScouts(){enemies=[{x:26,y:11,hp:4,max:4,kind:'scout',wind:0,hit:0,attackCd:0,stun:0},{x:29,y:16,hp:4,max:4,kind:'archer',wind:0,hit:0,attackCd:.8,stun:0},{x:25,y:19,hp:4,max:4,kind:'scout',wind:0,hit:0,attackCd:.3,stun:0}]}
function makeBoss(){enemies=[{x:33,y:14,hp:16,max:16,kind:'captain',wind:0,hit:0,attackCd:1,stun:0}]}
function restore(){if(!saved)return;phase=Math.max(0,Math.min(4,saved.phase||0));player.hp=Math.max(1,Math.min(player.max,saved.hp||100));player.st=Math.max(35,Math.min(player.maxSt,saved.st||100));player.xp=saved.xp||0;player.kills=saved.kills||0;player.level=saved.level||1;player.potions=saved.potions||0;chestOpen=!!saved.chestOpen;captainTalk=!!saved.captainTalk;gameWon=!!saved.gameWon;player.x=phase>=3?28:8.5;player.y=phase>=3?14.5:14.5;if(phase===2)makeScouts();if(phase===3)makeBoss()}
makeMap();restore();
function toast(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function updateUI(){const title='Die Belagerung von Eisenwacht';el('chapterTop').textContent='Kapitel I · '+title;el('chapterLabel').textContent='KAPITEL I · NORDWESTEN';el('questTitle').textContent=gameWon?'Eisenwacht hält stand':title;let copy=['Sprich mit Hauptmann Runa im Innenhof. Sie führt die menschliche Garnison.','Die Elfen greifen an. Öffne die Vorratskiste am Westwall — darin sind Heiltrank und Ausdauerproviant.','Drei elfische Angreifer sind durch das Osttor gelangt. Wehre die Späher und ihren Bogenschützen ab.','Die Waldläufer-Hauptfrau Elaris stellt sich am Feld. Blocke ihren schweren Hieb oder rolle im richtigen Moment aus.','Elaris ist besiegt. Eisenwacht ist sicher — der Weg nach Süden kann vorbereitet werden.'];el('questCopy').textContent=copy[phase];
 let objectives=['Hauptmann Runa ansprechen','Vorratskiste öffnen','Elfische Angreifer besiegen','Waldläufer-Hauptfrau Elaris besiegen','Kapitel abgeschlossen'];el('objective').innerHTML='Ziel: <strong>'+objectives[phase]+'</strong>'+(phase===2?` <span>${3-enemies.length} / 3</span>`:'');el('areaTag').textContent=phase<2?'FESTUNG EISENWACHT':phase<4?'OSTTOR · SCHLACHTFELD':'EISENWACHT SICHER';el('enemyLabel').textContent=phase===2?'Elfische Späher & Bogenschütze':phase===3?'Elaris · Waldläufer-Hauptfrau':'Keine aktiven Feinde';el('levelText').textContent=String(player.level).padStart(2,'0');el('killsText').textContent=player.kills;el('progressText').innerHTML=`<span class="faction human">MENSCHEN · Stahlblau, Rundschild</span><br><span class="faction elf">ELFEN · Blattgrün, spitze Ohren</span><br>Tränke: <b>${player.potions}</b>`;el('hpText').textContent=`${Math.ceil(player.hp)} / ${player.max}`;el('hpBar').style.width=`${100*player.hp/player.max}%`;el('stText').textContent=`${Math.ceil(player.st)} / ${player.maxSt}`;el('stBar').style.width=`${100*player.st/player.maxSt}%`;el('xpText').textContent=`${player.xp} / 100`;el('xpBar').style.width=`${player.xp}%`;}
function beginFight(){phase=2;makeScouts();toast('Das Osttor ist gefallen! Drei Angreifer im Hof.');updateUI();save()}
function completeFight(){if(enemies.length)return;if(phase===2){phase=3;makeBoss();toast('Ein Hornruf: Elaris, die Hauptfrau, tritt vor!');}else if(phase===3){phase=4;gameWon=true;player.hp=player.max;toast('Elaris ist gefallen · Eisenwacht ist sicher!');}updateUI();save()}
function stand(x,y){let tx=Math.floor(x),ty=Math.floor(y);return inside(tx,ty)&&![1,2].includes(tiles[idx(tx,ty)])}
function move(dx,dy,dt,speed=4.2){if(!dx&&!dy)return;const nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(stand(nx,player.y))player.x=nx;if(stand(player.x,ny))player.y=ny;if(Math.abs(dx)>Math.abs(dy))player.face=dx>0?'right':'left';else player.face=dy>0?'down':'up'}
function facingVector(){return {up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[player.face]}
function attack(){if(!gameStarted||player.atk>0||player.st<12||phase<2||phase>3)return;player.st-=12;player.stDelay=1;player.atk=.28;player.combo=(player.combo+1)%3;const [dx,dy]=facingVector();let target=null,best=1.75;for(const e of enemies){let vx=e.x-player.x,vy=e.y-player.y,d=Math.hypot(vx,vy),dot=(vx*dx+vy*dy)/(d||1);if(d<best&&dot>.05){best=d;target=e}}if(target){let dmg=player.combo===2?2:1;target.hp-=dmg;target.hit=.18;target.stun=.16;target.x+=dx*.25;target.y+=dy*.25;shake=3;if(target.hp<=0){enemies.splice(enemies.indexOf(target),1);player.kills++;player.xp+=target.kind==='captain'?50:25;if(player.xp>=100){player.xp-=100;player.level++;player.max+=10;player.hp=Math.min(player.max,player.hp+20);toast('Stufe '+player.level+' · Maximalleben erhöht!')}else toast(target.kind==='captain'?'Elaris besiegt!':'Elfischer Angreifer besiegt');completeFight()}else toast('Treffer · '+target.hp+' Leben übrig')}else toast('Der Hieb geht ins Leere');updateUI()}
function dodge(){if(!gameStarted||player.dodge>0||player.st<26)return;let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);if(!dx&&!dy){[dx,dy]=facingVector()}else if(dx&&dy){dx*=.707;dy*=.707}player.st-=26;player.stDelay=1;player.dodge=.24;player.invul=.3;player.rollX=dx;player.rollY=dy;toast('Ausweichrolle!');updateUI()}
function isFacingThreat(e){let [dx,dy]=facingVector(),vx=e.x-player.x,vy=e.y-player.y;return vx*dx+vy*dy>0}
function damage(amount,e){if(player.invul>0)return;if(player.blocking&&player.st>=8&&isFacingThreat(e)){player.st=Math.max(0,player.st-8);player.stDelay=.8;e.stun=.75;e.attackCd=.8;shake=1;toast('Block! Der Angriff prallt ab');}else{player.hp-=amount;player.invul=.7;shake=5;toast('Getroffen · '+Math.max(0,Math.ceil(player.hp))+' Leben');if(player.hp<=0){player.hp=55;player.st=55;player.x=8.5;player.y=14.5;if(phase===2)makeScouts();if(phase===3)makeBoss();toast('Zurück in Eisenwacht · der Angriff beginnt erneut');save()}}updateUI()}
function interact(){if(!gameStarted)return;if(phase===0&&Math.hypot(player.x-10,player.y-13)<2.1){captainTalk=true;phase=1;toast('Runa: „Halt das Tor. Nimm Vorräte und kämpf mit Bedacht.“');updateUI();save();return}if(phase===1&&Math.hypot(player.x-5.5,player.y-18)<2.2&&!chestOpen){chestOpen=true;player.potions++;player.hp=player.max;player.st=player.maxSt;toast('Vorratskiste: Heiltrank + volle Ausdauer');updateUI();save();return}if(phase===4&&Math.hypot(player.x-10,player.y-13)<2.1){toast('Runa: „Eisenwacht wird deinen Namen erinnern.“');return}if(phase===0)toast('Finde Hauptmann Runa im Innenhof (goldener Umhang).');else if(phase===1)toast('Die Vorratskiste steht am Westwall.');else toast('Keine Interaktion in Reichweite.')}
function usePotion(){if(player.potions>0&&player.hp<player.max){player.potions--;player.hp=Math.min(player.max,player.hp+45);toast('Heiltrank · +45 Leben');updateUI();save()}else toast(player.potions?'Dein Leben ist bereits voll.':'Keine Heiltränke übrig.')}

